fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    assert!(!a.is_empty() && !b.is_empty(), "inputs must be non-empty");

    let m = a.len();
    let n = b.len();

    // Compatibility assumption (also enforced here for safety).
    assert!(
        m == n || m == 1 || n == 1,
        "incompatible lengths: a.len()={}, b.len()={}",
        m,
        n
    );

    let out_len = m.max(n);

    let out_a = if m == out_len {
        a
    } else {
        vec![a[0]; out_len]
    };

    let out_b = if n == out_len {
        b
    } else {
        vec![b[0]; out_len]
    };

    (out_a, out_b)
}